					      &FR_DBUFF_TMP(ptr, attr_len), attr_len, true) < 0) {
			talloc_free(vp);
			return -1;
		}

		ptr += attr_len;
		vp->vp_tainted = true;
		DEBUG2("&%pP", vp);
		fr_dcursor_append(cursor, vp);
